let text = "";

if ($json.content?.parts?.[0]?.text) {
  text = $json.content.parts[0].text;
} else if ($json.candidates?.[0]?.content?.parts?.[0]?.text) {
  text = $json.candidates[0].content.parts[0].text;
} else {
  throw new Error("Structure Gemini inconnue : " + JSON.stringify($json));
}

// Nettoyer le markdown et caractères problématiques
const cleaned = text
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .replace(/[\u0000-\u001F\u007F]/g, " ") // caractères de contrôle
  .replace(/,\s*}/g, "}")                  // virgule avant }
  .replace(/,\s*]/g, "]")                  // virgule avant ]
  .trim();

// Extraire uniquement le bloc JSON entre { }
const match = cleaned.match(/\{[\s\S]*\}/);
if (!match) throw new Error("Aucun JSON trouvé dans la réponse : " + cleaned);

const data = JSON.parse(match[0]);

return [{ json: data }];

const item = $input.first();

// Récupérer le buffer binaire
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');

// Convertir en base64
const base64String = binaryBuffer.toString('base64');

return [{
  json: {
    fileName: item.binary.data.fileName,
    mimeType: item.binary.data.mimeType,
    fileBase64: base64String
  },
  binary: item.binary
}];

const item = $input.first();
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
