const openRouterApiKey = process.env.OPENROUTER_API_KEY;
if (!openRouterApiKey) {
  throw new Error('Missing OPENROUTER_API_KEY in n8n environment');
}

const competences = $json.competences_techniques || "";
const intitule = $json.intitule_poste || "";
const domaine = $json.dominante || "";

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/chat/completions',
  headers: {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${openRouterApiKey}`
  },
  body: JSON.stringify({
    model: 'nvidia/nemotron-3-super-120b-a12b:free',
    messages: [{
      role: 'user',
      content: `Tu es un expert RH et technique. Analyse ce poste et réponds UNIQUEMENT par true ou false, sans rien d'autre.

Règle : retourne true si le poste nécessite d'écrire, lire ou analyser du code (développeur, data engineer, DevOps, data scientist, ML engineer...). Retourne false pour tout autre poste (finance, RH, marketing, juridique, commercial, management...).

Intitulé du poste : ${intitule}
Dominante : ${domaine}
Compétences techniques : ${competences}

Réponse (true ou false uniquement) :`
    }]
  })
});

const raw = response.choices[0].message.content.trim().toLowerCase();
const requires_coding = raw === "true";

return [{
  json: {
    ...$json,
    requires_coding
  }
}];

